import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`ad-account-audit`,heroTitle:`Audit your ad account in minutes`,heroSubtitle:`Perplexity Computer analyzes your campaign structure, spend, targeting, creatives, and landing pages, then finds what to fix first.`,inputUrlCta:`Audit my ads`,inputUrlPlaceholder:`e.g. ad dashboard, report, or landing page URL`,inputUrlPrefill:`Go to {url} and audit the ad account or campaign report. (1) Analyze campaign structure, spend allocation, targeting, creatives, landing pages, tracking, and performance trends. (2) Identify wasted spend, weak segments, creative fatigue, conversion bottlenecks, and missing tests. (3) Prioritize fixes by expected impact, confidence, and effort. (4) Recommend budget shifts, testing plans, copy updates, landing page improvements, and tracking checks. (5) Deliver an ad account audit with findings, evidence, and a prioritized action plan.`,heroOverlaySteps:[`Analyzing campaign structure, spend, targeting, creatives, and landing pages`,`Finding wasted spend, weak segments, creative fatigue, and conversion gaps`,`Prioritizing fixes by impact, confidence, and effort`,`Ad account audit with evidence and action plan, ready to review`],generatingSteps:[`Reading {url} to review campaign structure, spend, and performance context`,`Designing an agent to identify wasted spend, weak segments, and creative issues`,`Configuring prioritization for impact, confidence, and effort`,`Preparing an ad account audit with recommendations and next steps`],featureSectionTitle:`From messy ad data to a prioritized fix list`,featureCardTitles:[`Connects to your acquisition stack`,`Outputs you can act on`],featureCardDescriptions:[`Computer breaks the audit into focused tasks, spins up specialized agents, and matches each task to the AI model that fits it best.`,`Ad reports, landing pages, spreadsheets, docs, creative libraries, and Slack can stay connected so the audit reflects the whole funnel.`,`Spend issues. Targeting gaps. Creative fatigue. Landing page fixes. Computer gives you a prioritized action plan for better performance.`],capabilitySectionTitle:`Your performance marketing auditor, on demand`,capabilitySectionSubtitle:`Share your ad context, step away, and come back to a practical account audit.`,capabilityCards:[{title:`Campaign Structure Review`,description:`Computer can analyze campaigns, ad groups, targeting, budgets, tracking, and landing page alignment.`},{title:`Waste Detection`,description:`Computer can flag wasted spend, weak segments, low-confidence tests, creative fatigue, and conversion bottlenecks.`},{title:`Action Prioritization`,description:`Computer can rank recommendations by expected impact, confidence, effort, and urgency.`},{title:`Connect Your Tools`,description:`Computer can organize findings across ad reports, spreadsheets, docs, creative folders, and marketing workflows.`},{title:`Testing Plan`,description:`Computer can recommend copy tests, audience tests, budget shifts, and landing page improvements.`},{title:`Follow-Up Monitoring`,description:`Computer can prepare the metrics and checkpoints your team should watch after changes go live.`}]});export{t as default};
